export function insertStructure(db, ws, axis, request) {
  const total = axis === 'row' ? ws.row_count : ws.col_count;
  const cap = axis === 'row' ? MAX_ROW_COUNT : MAX_COL_COUNT;
  if (request.index >= total) {
